def fill_origin_domain(apps: Apps, schema_editor: BaseDatabaseSchemaEditor) -> None:
    """An existing programme's origin is the page its earliest evidence claim
    cites; a row with no evidence keeps "". Under a role RLS filters out of
    funding_program writes this updates nothing, so say so rather than pass
    silently -- `manage.py backfill_evidence_domain` fills the rest."""
    program_model = apps.get_model("funding", "Program")
    link_model = apps.get_model("funding", "ProgramEvidenceClaim")
    first_url: dict[UUID, str] = {}
    for program_id, url in link_model.objects.order_by("id").values_list(
        "program_id", "evidence_claim__source__canonical_url"
    ):
        first_url.setdefault(program_id, url)
    updated = 0
    for program_id, url in first_url.items():
        updated += program_model.objects.filter(id=program_id, origin_domain="").update(
            origin_domain=registrable_domain(url)
        )
    if updated < len(first_url):
        print(
            f"\n  origin_domain set on {updated} of {len(first_url)} programmes with "
            f"evidence; run manage.py backfill_evidence_domain for the rest"
        )


